package org.hnau.ktcad

import org.hnau.ktcad.axis.A3
import org.hnau.ktcad.axis.A3Values
import org.hnau.ktcad.axis.direction
import org.hnau.ktcad.axis.times
import org.hnau.commons.kotlin.foldBoolean

/**
 * Hand-written factories for primitives whose placement can be centred on demand.
 *
 * `box`/`cylinder` are generated by KSP like the other `Body` variants, but the generated factory
 * has no centring sugar; these replace it (the generator skips `Box`/`Cylinder`). The IR node is
 * unchanged — centring is a `translate`, i.e. pure DSL sugar.
 */

/**
 * A box with its corner at the origin, extending into the `+` octant. [centered] shifts it by half
 * its size along every axis flagged there, so it is centred on those axes instead.
 */
fun box(
    size: A3Values<Double>,
    centered: A3Values<Boolean> = A3Values.create { false },
): Solid {
    val box = Solid.Box(
        width = size[A3.X],
        length = size[A3.Y],
        height = size[A3.Z],
    )
    if (A3.entries.none { centered[it] }) return box
    return box.translate(
        size.combineWith(other = centered) { value, isCentered ->
            isCentered.foldBoolean(
                ifTrue = { -value / 2 },
                ifFalse = { 0.0 },
            )
        },
    )
}

/**
 * A cylinder with its base at the origin and axis `+Z`. An [angle] makes a cylindrical wedge. Its
 * base is already centred on the `Z` axis, so only `centerZ` is offered (shifts by half its height).
 */
fun cylinder(
    radius: Double,
    height: Double,
    angle: Double? = null,
    centerZ: Boolean = false,
): Solid {
    val cylinder = Solid.Cylinder(
        radius = radius,
        height = height,
        angle = angle,
    )
    return if (centerZ) cylinder.translate(A3.Z.direction * (-height / 2)) else cylinder
}
